mapper.select:
/* selectpensnCrtf - 이승재 청소년쉼터 입소기간 확인서(자립지원수당 신청용) 등록 */ SELECT G.INST_NM /*기관명*/ , G.RPRS_TELNO /*대표전화번호*/ , G.BPLC_PST_ADDR || ' ' || G.BPLC_DADDR AS BPLC_ADDR /*사업장 우편주소*/ , G.INST_NO /*기관번호*/ , F.INST_NM AS PENSN_INST_NM /*쉼터명*/ , (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'FCLTY_TYPE_SE_CD' AND CMMNS_CD_VALUE = I.FCLTY_TYPE_SE_CD) AS SHELTR_TYPE /*쉼터유형*/ , B.CASE_BGNG_YMD AS CASE_BGNG_YMD /*서비스 시작 일시(사례시작일시)*/ , B.CASE_TRMN_YMD AS CASE_TRMN_YMD /*서비스 종료 일시(사례종결일시)*/ , TRUNC(MONTHS_BETWEEN(B.CASE_TRMN_YMD, B.CASE_BGNG_YMD) / 12) AS ENTSC_PRD_YR /*입소기간 - 년*/ , TRUNC(MOD(MONTHS_BETWEEN(B.CASE_TRMN_YMD, B.CASE_BGNG_YMD) / 12, 1) * 12) AS ENTSC_PRD_MM /*입소기간 - 월*/ , LEAST(TO_DATE(B.CASE_TRMN_YMD) - ADD_MONTHS(B.CASE_BGNG_YMD, FLOOR(MONTHS_BETWEEN(B.CASE_TRMN_YMD, B.CASE_BGNG_YMD))), 29) AS ENTSC_PRD_DD /*입소기간 - 일*/ /* , TRUNC(MOD(MOD(MONTHS_BETWEEN(B.CASE_TRMN_YMD, B.CASE_BGNG_YMD) / 12, 1) * 12, 1) * (365 / 12)) */ , CASE WHEN TRUNC(MONTHS_BETWEEN(TO_DATE(MAX(B.CASE_TRMN_YMD) OVER(), 'YYYYMMDD'), TO_DATE(D.TRPR_BRTH_YMD, 'YYYYMMDD')) /12) >= 18 THEN 'Y' ELSE 'N' END AS AGEA_CND_YN , CASE WHEN MAX(B.CASE_TRMN_YMD) OVER() > '20201231' THEN 'Y' ELSE 'N' END AS YR_CND_YN , B.CASE_MNG_NO /*사례관리번호*/ , B.CASE_MNG_ODRNO /*사례관리차수*/ FROM SEB100 B /*사례기본 테이블*/ LEFT JOIN SEB150 C /*사례담당자*/ ON B.CASE_MNG_NO = C.CASE_MNG_NO AND B.CASE_MNG_ODRNO = C.CASE_MNG_ODRNO AND C.PCHPRS_YN = 'Y' INNER JOIN SAA000 F /*통합기관 - 쉼터명을 가지기 위한 번호*/ ON C.PIC_INST_NO = F.INST_NO LEFT OUTER JOIN SAA000 G /*통합기관 테이블 담당자 기관번호*/ ON 1=1 LEFT JOIN AKA500 I ON C.PIC_INST_NO = I.INST_NO AND I.FCLTY_TYPE_SE_CD IN ('03', '04') /* 단기쉼터, 중장기쉼터 */ LEFT JOIN SEA200 D ON B.TRPR_INFO_NO = D.TRPR_INFO_NO
WHERE B.TRPR_INFO_NO IN (SELECT TRPR_INFO_NO FROM SEA200 WHERE UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} AND INDV_IDNTFC_NO IN (SELECT INDV_IDNTFC_NO FROM SEA200 WHERE TRPR_INFO_NO = #{TRPR_INFO_NO}) UNION SELECT TRPR_INFO_NO FROM SEA200 WHERE TRPR_INFO_NO = #{TRPR_INFO_NO}) AND B.CASE_PRGRS_STTS_SE_CD IN ('04', '06', '07', '08', '09', '10', '11') AND B.CASE_TRMN_YMD >= TO_CHAR(TO_DATE(#{LASTA_TRMN_YMD}, 'YYYYMMDD') - (INTERVAL '3' YEAR), 'YYYYMMDD') AND G.INST_NO = #{INST_NO} /*기관번호(세션에서 받아오는)*/
ORDER BY B.CASE_BGNG_YMD

/* 서비스이용 상세 확인서(건별)_리스트(상세조회) */
SELECT DEC_B64(H.TRPR_NM_ENCPT) AS TRPR_NM_ENCPT /*대상자명암호화*/ , H.TRPR_BRTH_YMD AS TRPR_BRTH_YMD /*대상자 출생일자*/ , H.PST_ADDR /*대상자 우편주소*/ , H.DADDR /*대상자 상세주소*/ , H.ZIP /*우편번호*/ , NVL2(H.ZIP, '[' || H.ZIP || ']', '') || H.PST_ADDR || ' ' || H.DADDR AS TRPR_ADDR /*대상자 우편주소 + 상세주소*/ , H.TRPR_INFO_NO AS TRPR_INFO_NO /*대상자정보번호*/ , I.INST_NM AS INST_NM /*기관명*/ , I.INST_NO AS INST_NO /*기관명*/ , I.RPRS_TELNO AS RPRS_TELNO /*대표전화번호*/ , I.BPLC_PST_ADDR || ' ' || I.BPLC_DADDR AS BPLC_ADDR /*사업장 우편주소 + 상세주소*/ , E.PVSN_RESRCE_NM AS PVSN_RESRCE_NM /*제공자원명*/ , J.SRVC_PVSN_BGNG_YMD AS SRVC_PVSN_BGNG_YMD /*서비스제공시작일자*/ , J.SRVC_PVSN_END_YMD AS SRVC_PVSN_END_YMD /*서비스제공종료일자*/ , J.SRVC_PVSN_CN AS SRVC_PVSN_CN /*서비스제공 내용*/ , D.SRVC_PVSN_RESULT_CN AS SRVC_PVSN_RESULT_CN /*서비스결과 내용*/ , A.USE_FSBTY_NM AS USE_FSBTY_NM /*사용용도명*/ , A.RCPDSK_NM AS RCPDSK_NM /*제출처명*/ , A.CRTF_ISSU_MNG_NO AS CRTF_ISSU_MNG_NO /*증명서발급관리번호*/ ,B.CRTF_ISSU_SN AS CRTF_ISSU_SN /* 증명서발급일련번호 */
FROM SAB700 A /* 증명서관리 */ LEFT JOIN SEA200 H /* 대상자정보 */ ON A.TRPR_INFO_NO = H.TRPR_INFO_NO -- 대상자정보번호 LEFT JOIN SAA000 I /* 통합기관 */ ON A.ISSU_INST_NO = I.INST_NO -- 기관번호 LEFT JOIN SAB701 B /* 증명서관리상세 */ ON A.CRTF_ISSU_MNG_NO = B.CRTF_ISSU_MNG_NO -- 증명서발급관리번호 LEFT JOIN SDA100 E /* 자원기본 */ ON B.RESRCE_NO = E.RESRCE_NO -- 자원번호 AND E.USE_YN = 'Y' LEFT JOIN SEB500 J /* 서비스제공 */ ON J.SRVC_PVSN_NO = B.SRVC_PVSN_NO -- 서비스제공번호 AND J.RESRCE_NO = B.RESRCE_NO -- 자원번호 AND J.DEL_YN != 'Y' LEFT JOIN SEB100 C ON C.TRPR_INFO_NO = A.TRPR_INFO_NO LEFT JOIN SEB510 D /* 서비스제공대상자 */ ON D.SRVC_PVSN_NO = B.SRVC_PVSN_NO -- 서비스제공번호 AND D.RESRCE_NO = B.RESRCE_NO -- 자원번호 AND D.CASE_MNG_NO = C.CASE_MNG_NO AND D.CASE_MNG_ODRNO = C.CASE_MNG_ODRNO AND D.DEL_YN != 'Y' WHERE A.CRTF_ISSU_MNG_NO = #{CRTF_ISSU_MNG_NO} -- 증명서발급관리번호(입력 : CRTF_ISSU_MNG_NO) AND A.CRTF_SE_CD = #{CRTF_SE_CD} -- 증명서구분코드

/* 종사자 상담경력 확인서 리스트(상세조회) */
SELECT DEC_B64(FLNM_ENCPT) AS FLNM , BRTH_YMD , INST_NM /*기관명*/ , INST_NO /*기관번호*/ , RPRS_TELNO /*대표전화번호*/ , BPLC_ADDR /*사업장 우편 + 상세 주소*/ , YR /*년도*/ , INDV_DSCSN_CONT /*해당년도 개인상담(대면)의 횟수*/ , TRUNC(GR_DSCSN_HR / 60) || '시간' || (GR_DSCSN_HR - TRUNC(GR_DSCSN_HR / 60) * 60 || '분') AS GR_DSCSN_HR /*해당년도 집단상담 시간*/ , GR_DSCSN_HR AS GR_DSCSN_HR2 /*해당년도 집단상담 시간*/ , TRL_DSCSN_CONT /*해당년도 심리상담의 사례 수*/ , USE_FSBTY_NM /*사용용도명*/ , RCPDSK_NM /*제출처명*/ , CRTF_ISSU_MNG_NO /*증명서발급관리번호*/ FROM( SELECT C.FLNM_ENCPT AS FLNM_ENCPT /*종사자명암호화*/ , C.BRTH_YMD AS BRTH_YMD /*종사자생년월일*/ , G.INST_NM AS INST_NM /*기관명*/ , G.INST_NO AS INST_NO /*기관명*/ , G.RPRS_TELNO AS RPRS_TELNO /*대표전화번호*/ , G.BPLC_PST_ADDR || ' ' || G.BPLC_DADDR AS BPLC_ADDR /*사업장 우편 + 상세 주소*/ , SUBSTR(D.SRVC_PVSN_BGNG_YMD, 1,4) AS YR /*년도*/ , COUNT(CASE WHEN F.SRVC_RESRCE_MLSFC_SE_CD = '0101' AND D.SRVC_PVSN_MTHD_SE_CD IN ('02','04') THEN 1 END ) AS INDV_DSCSN_CONT /*해당년도 개인상담(대면)의 횟수*/ , SUM(CASE WHEN F.SRVC_RESRCE_MLSFC_SE_CD = '0102' AND (SELECT COUNT(1) FROM SEB510 WHERE SRVC_PVSN_NO = D.SRVC_PVSN_NO AND RESRCE_NO = D.RESRCE_NO) >= 5 THEN ROUND((TO_DATE(SRVC_PVSN_END_HR,'HH24:MI') - TO_DATE(SRVC_PVSN_BGNG_HR,'HH24:MI')) *24*60) ELSE 0 END) AS GR_DSCSN_HR /*해당년도 집단상담 시간의 총합*/ /*해당년도 집단상담 시간*/ , COUNT(CASE WHEN F.SRVC_RESRCE_MLSFC_SE_CD = '0104' THEN '1' END ) AS TRL_DSCSN_CONT /*해당년도 심리상담의 사례 수*/ , A.USE_FSBTY_NM AS USE_FSBTY_NM /*사용용도명*/ , A.RCPDSK_NM AS RCPDSK_NM /*제출처명*/ , A.CRTF_ISSU_MNG_NO AS CRTF_ISSU_MNG_NO /*증명서발급관리번호*/ FROM SAB700 A --증명서관리 테이블 INNER JOIN SCA100 C --종사자 테이블 ON A.TRPR_INFO_NO = C.ENFSN_NO /*종사자번호*/ LEFT JOIN SEB500 D --서비스제공 테이블 ON C.ENFSN_NO = D.PIC_NO /*담당자번호(종사자번호)*/ AND D.DEL_YN != 'Y' LEFT JOIN SDA100 F --자원기본 테이블 ON D.RESRCE_NO = F.RESRCE_NO /*자원번호*/ AND F.SRVC_RESRCE_LCLAS_SE_CD = '01' LEFT JOIN SAA000 G --통합기관 테이블 ON G.INST_NO = A.ISSU_INST_NO /*기관번호*/ WHERE A.CRTF_ISSU_MNG_NO = #{CRTF_ISSU_MNG_NO} /*증명서발급관리번호*/ AND A.CRTF_SE_CD = #{CRTF_SE_CD} /*증명서구분코드*/ GROUP BY SUBSTR(D.SRVC_PVSN_BGNG_YMD, 1,4) /*년도*/ , C.FLNM_ENCPT /*종사자명 암호화*/ , C.BRTH_YMD /*출생일자*/ , G.INST_NM /*기관명*/ , G.RPRS_TELNO /*대표전화번호*/ , G.BPLC_PST_ADDR || ' ' || G.BPLC_DADDR /*사업장 우편 + 상세 주소*/ , A.USE_FSBTY_NM /*사용용도명*/ , A.RCPDSK_NM /*제출처명*/ , A.CRTF_ISSU_MNG_NO /*증명서발급관리번호*/ , G.INST_NO
ORDER BY SUBSTR(D.SRVC_PVSN_BGNG_YMD, 1,4) )

/* 청소년 입소기간 확인서(자립지원수당 신청용) 리스트(상세조회) */
SELECT DEC_B64(F.TRPR_NM_ENCPT) AS TRPR_NM_ENCPT /*대상자명암호화*/ , DEC_B64(F.MBL_TELNO_ENCPT) AS MBL_TELNO_ENCPT /*대상자전화번호*/ , DEC_B64(G.RRNO_ENCPT) AS RRNO_ENCPT /*대상자 주민번호*/ , F.TRPR_TELNO AS TRPR_TELNO /*대상자전화번호*/ , F.PST_ADDR AS PST_ADDR /*대상자 우편주소*/ , F.DADDR AS DADDR /*대상자 상세주소*/ , F.ZIP AS ZIP /*우편번호*/ , NVL2(F.ZIP, '[' || F.ZIP || ']', '') || F.PST_ADDR || ' ' || F.DADDR AS ADDR /*대상자 우편번호 + 우편주소 + 상세주소*/ , I.INST_NM AS INST_NM /*기관명 발급기관*/ , I.INST_NO AS INST_NO /*기관명 발급기관*/ , I.RPRS_TELNO AS RPRS_TELNO /*대표전화번호*/ , I.BPLC_PST_ADDR || ' ' || I.BPLC_DADDR AS BPLC_ADDR /*사업장 우편+상세주소*/ , B.INST_NO AS PENSN_INST_NO /*쉼터기관번호 담당자기관*/ , NVL(CASE WHEN B.INST_NO IS NULL THEN H.INST_NM ELSE J.INST_NM END, B.INST_NM) AS PENSN_INST_NM /*쉼터명 담당자기관*/ , (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'FCLTY_TYPE_SE_CD' AND CMMNS_CD_VALUE = K.FCLTY_TYPE_SE_CD) AS SHELTR_TYPE /*쉼터유형*/ , CASE WHEN B.CASE_MNG_NO IS NULL THEN B.CASE_BGNG_YMD ELSE C.CASE_BGNG_YMD END AS CASE_BGNG_YMD /*서비스 시작 일시(사례시작일시)*/ , CASE WHEN B.CASE_MNG_NO IS NULL THEN B.CASE_TRMN_YMD ELSE C.CASE_TRMN_YMD END AS CASE_TRMN_YMD /*서비스 종료 일시(사례종결일시)*/ , CASE WHEN B.CASE_MNG_NO IS NULL THEN TRUNC(MONTHS_BETWEEN(B.CASE_TRMN_YMD, B.CASE_BGNG_YMD) / 12) ELSE TRUNC(MONTHS_BETWEEN(C.CASE_TRMN_YMD, C.CASE_BGNG_YMD) / 12) END AS ENTSC_PRD_YR /*입소기간 - 년*/ , CASE WHEN B.CASE_MNG_NO IS NULL THEN TRUNC(MOD(MONTHS_BETWEEN(B.CASE_TRMN_YMD, B.CASE_BGNG_YMD) / 12, 1) * 12) ELSE TRUNC(MOD(MONTHS_BETWEEN(C.CASE_TRMN_YMD, C.CASE_BGNG_YMD) / 12, 1) * 12) END AS ENTSC_PRD_MM /*입소기간 - 월*/ , CASE WHEN B.CASE_MNG_NO IS NULL THEN LEAST(TO_DATE(B.CASE_TRMN_YMD) - ADD_MONTHS(B.CASE_BGNG_YMD, FLOOR(MONTHS_BETWEEN(B.CASE_TRMN_YMD, B.CASE_BGNG_YMD))), 29) ELSE LEAST(TO_DATE(C.CASE_TRMN_YMD) - ADD_MONTHS(C.CASE_BGNG_YMD, FLOOR(MONTHS_BETWEEN(C.CASE_TRMN_YMD, C.CASE_BGNG_YMD))), 29) END AS ENTSC_PRD_DD /*입소기간 - 일*/ , A.USE_FSBTY_NM AS USE_FSBTY_NM /*사용용도명*/ , A.RCPDSK_NM AS RCPDSK_NM /*제출처명*/ , A.CTNUTN_ENTRNC_YN AS CTNUTN_ENTRNC_YN /*연속입소 여부*/ , A.RECENT_PRD_YR AS RECENT_PRD_YR /*3년입소년*/ , A.RECENT_PRD_MM AS RECENT_PRD_MM /*3년입소월*/ , A.RECENT_PRD_YMD AS RECENT_PRD_DD /*3년입소일*/ , A.AGEA_CND_YN AS AGEA_CND_YN /*나이조건여부*/ , A.YR_CND_YN AS YR_CND_YN /*연도조건여부*/ , A.CRTF_ISSU_MNG_NO AS CRTF_ISSU_MNG_NO /*증명서발급관리번호*/ , B.CASE_MNG_NO AS CASE_MNG_NO /*사례관리번호*/ , B.CASE_MNG_ODRNO AS CASE_MNG_ODRNO /*사례관리차수*/ , B.CRTF_ISSU_SN AS CRTF_ISSU_SN /*증명서 일련번호*/ FROM SAB700 A --증명서 관리 테이블 INNER JOIN SAB701 B --증명서 관리 상세 테이블 ON A.CRTF_ISSU_MNG_NO = B.CRTF_ISSU_MNG_NO /*증명서발급관리번호*/ LEFT JOIN SEB100 C --사례기본 테이블 ON B.CASE_MNG_NO = C.CASE_MNG_NO /*사례관리번호*/ AND B.CASE_MNG_ODRNO = C.CASE_MNG_ODRNO /*사례관리차수*/ LEFT JOIN SEB150 D --사례담당자 테이블 ON B.CASE_MNG_NO = D.CASE_MNG_NO /*사례관리번호*/ AND B.CASE_MNG_ODRNO = D.CASE_MNG_ODRNO /*사례관리차수*/ AND D.PCHPRS_YN = 'Y' LEFT JOIN SEA200 F --대상자정보 테이블 ON A.TRPR_INFO_NO = F.TRPR_INFO_NO /*대상자정보번호*/ LEFT JOIN SCA300 G --개인정보 테이블 ON F.INDV_IDNTFC_NO = G.INDV_IDNTFC_NO /*개인식별번호*/ LEFT JOIN SAA000 H --통합기관 테이블 ON D.PIC_INST_NO = H.INST_NO /*기관번호*/ LEFT OUTER JOIN SAA000 I --통합기관 테이블 ON A.ISSU_INST_NO = I.INST_NO /*기관번호*/ LEFT OUTER JOIN SAA000 J --통합기관 테이블 ON B.INST_NO = J.INST_NO /*기관번호*/ LEFT JOIN AKA500 K ON K.INST_NO = H.INST_NO WHERE A.CRTF_ISSU_MNG_NO = #{CRTF_ISSU_MNG_NO} /*증명서발급관리번호*/ AND A.CRTF_SE_CD = #{CRTF_SE_CD} /*증명서구분코드*/
ORDER BY B.CRTF_ISSU_SN

/* 직인 관련 내용 조회 selectOffcs Lee.Seoung.Jae */
SELECT C.STRG_COURS_NM , C.REAL_FILE_NM , C.FILE_SZ , C.FILE_EXTN_NM , C.ATFINO , C.MNG_SN , C.STRG_FILE_NM FROM SAA230 A INNER JOIN SAA000 B ON B.OFFCS_SGNNG_NO = A.OFFCS_SGNNG_NO INNER JOIN SAB881 C ON A.ATFINO = C.ATFINO AND TO_CHAR(A.ATCMFL_MNG_SN) = C.ATCMFL_CL_NM
WHERE A.OFFCS_SGNNG_SE_CD = '01' AND A.USE_YN = 'Y' AND B.INST_NO = #{OFFCS_INST_NO}

/* 직인 관련 내용 조회 selectOffcsPic Lee.Seoung.Jae */
SELECT C.STRG_COURS_NM , C.REAL_FILE_NM , C.FILE_SZ , C.FILE_EXTN_NM , C.ATFINO , C.MNG_SN , C.STRG_FILE_NM FROM SCA100 A INNER JOIN SAB881 C ON A.ATFINO = C.ATFINO
WHERE A.ENFSN_NO = #{OFFCS_PIC_NO} AND C.ATCMFL_CL_NM = '서명사진' AND C.FILE_STTS_SE_CD = 'N'
